OPJ_BOOL write_j2k_tile_part_first(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written, OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream, struct opj_event_mgr *p_manager) {
    OPJ_BYTE *data = p_data;
    OPJ_UINT32 data_size = p_total_data_size;

    /* Write SOT marker */
    if (data_size < 2) {
        opj_event_msg(p_manager, OPJ_EVT_ERROR, "Not enough space to write SOT marker\n");
        return OPJ_FALSE;
    }
    data[0] = 0xff;
    data[1] = 0x90;
    data += 2;
    data_size -= 2;

    /* Write SOT length, tile index, and number of tiles in the progression */
    if (data_size < 10) {
        opj_event_msg(p_manager, OPJ_EVT_ERROR, "Not enough space to write SOT header\n");
        return OPJ_FALSE;
    }
    OPJ_UINT32 sot_length = 10;
    OPJ_UINT32 tile_index = 0;
    OPJ_UINT32 num_tiles = 1;

    /* Write length (excluding the first two bytes) */
    memcpy(data, &sot_length, sizeof(OPJ_UINT32));
    data += 4;
    data_size -= 4;

    memcpy(data, &tile_index, sizeof(OPJ_UINT32));
    data += 4;
    data_size -= 4;

    memcpy(data, &num_tiles, sizeof(OPJ_UINT32));
    data += 2;
    data_size -= 2;

    /* Write tile component information if enabled */
    if (p_j2k->cinfo->tile_component_information) {
        if (data_size < 2) {
            opj_event_msg(p_manager, OPJ_EVT_ERROR, "Not enough space to write tile component information marker\n");
            return OPJ_FALSE;
        }
        data[0] = 0xff;
        data[1] = 0x91;
        data += 2;
        data_size -= 2;

        if (data_size < 4) {
            opj_event_msg(p_manager, OPJ_EVT_ERROR, "Not enough space to write tile component information header\n");
            return OPJ_FALSE;
        }

        OPJ_UINT32 tci_length = 4;
        memcpy(data, &tci_length, sizeof(OPJ_UINT32));
        data += 4;
        data_size -= 4;
    }

    /* Write SOD marker */
    if (data_size < 2) {
        opj_event_msg(p_manager, OPJ_EVT_ERROR, "Not enough space to write SOD marker\n");
        return OPJ_FALSE;
    }
    data[0] = 0xff;
    data[1] = 0x93;
    data += 2;
    data_size -= 2;

    *p_data_written = p_total_data_size - data_size;
    return OPJ_TRUE;
}

OPJ_BOOL write_j2k_first_tile_part(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 pos = 0;
    OPJ_BYTE sot[12];
    OPJ_UINT32 sot_len = 0;
    OPJ_UINT32 tcomps = p_j2k->tcp->tcomps;
    OPJ_UINT32 compno;

    /* Initialize and write SOT marker */
    sot_len = 0;
    opj_j2k_write_sot(p_j2k, sot, &sot_len, p_manager);
    if (pos + sot_len > p_total_data_size) {
        return OPJ_FALSE;
    }
    memcpy(p_data + pos, sot, sot_len);
    pos += sot_len;

    /* Write tile component information if required */
    if (p_j2k->tcp->tccp != NULL) {
        for (compno = 0; compno < tcomps; ++compno) {
            OPJ_UINT32 tcci_len = 0;
            OPJ_BYTE tcci[20]; /* Adjust size as needed */
            opj_j2k_write_tcci(p_j2k, compno, tcci, &tcci_len, p_manager);
            if (pos + tcci_len > p_total_data_size) {
                return OPJ_FALSE;
            }
            memcpy(p_data + pos, tcci, tcci_len);
            pos += tcci_len;
        }
    }

    /* Write SOD marker */
    if (pos + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    p_data[pos++] = 0xFF;
    p_data[pos++] = J2K_MS_SOD;

    *p_data_written = pos;

    return OPJ_TRUE;
}

OPJ_BOOL write_jpeg2000_tile_start(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written, OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream, struct opj_event_mgr *p_manager)
{
    OPJ_UINT32 data_written = 0;
    OPJ_UINT32 tile_data_size = 0;
    OPJ_UINT32 tile_offset = 0;

    /* Write SOT marker */
    if (data_written + 6 > p_total_data_size) {
        opj_event_msg(p_manager, OPJ_EVT_ERROR, "Not enough space to write SOT marker\n");
        return OPJ_FALSE;
    }

    /* Write SOT marker code (0xFF91) */
    p_data[data_written++] = 0xFF;
    p_data[data_written++] = 0x91;

    /* Write length of SOT segment (4 bytes, placeholder for now) */
    p_data[data_written++] = 0;
    p_data[data_written++] = 0;
    p_data[data_written++] = 0;
    p_data[data_written++] = 0;

    /* Write tile index and progression order, etc. (simplified) */
    /* Assume this is handled via helper functions or context data in p_j2k */
    if (!write_sot_segment(p_j2k, p_data, &data_written, p_total_data_size, p_manager)) {
        return OPJ_FALSE;
    }

    /* Conditionally write tile component information if required */
    if (p_j2k->cinema_mode) {
        if (!write_tile_component_info(p_j2k, p_data, &data_written, p_total_data_size, p_manager)) {
            return OPJ_FALSE;
        }
    }

    /* Write SOD marker */
    if (data_written + 2 > p_total_data_size) {
        opj_event_msg(p_manager, OPJ_EVT_ERROR, "Not enough space to write SOD marker\n");
        return OPJ_FALSE;
    }

    p_data[data_written++] = 0xFF;
    p_data[data_written++] = 0x93;

    *p_data_written = data_written;

    return OPJ_TRUE;
}

OPJ_BOOL write_j2k_first_tile(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                              OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                              struct opj_event_mgr *p_manager) {
    OPJ_BYTE *data = p_data;
    OPJ_UINT32 data_size = p_total_data_size;
    OPJ_UINT32 written = 0;

    if (!opj_j2k_write_sot(p_j2k, data + written, data_size - written, p_stream, p_manager)) {
        return OPJ_FALSE;
    }
    written += 10; /* SOT marker and length */

    if (p_j2k->cinema && p_j2k->cinfo->numcomps > 1) {
        if (!opj_j2k_write_tcomp_info(p_j2k, data + written, data_size - written, p_stream, p_manager)) {
            return OPJ_FALSE;
        }
        written += 2 * p_j2k->cinfo->numcomps;
    }

    if (!opj_j2k_write_sod(p_j2k, data + written, data_size - written, p_stream, p_manager)) {
        return OPJ_FALSE;
    }
    written += 1; /* SOD marker */

    *p_data_written = written;
    return OPJ_TRUE;
}

OPJ_BOOL write_j2k_first_tile(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written, OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream, struct opj_event_mgr *p_manager) {
    if (!p_j2k || !p_data || !p_data_written || !p_stream || !p_manager) {
        return OPJ_FALSE;
    }

    OPJ_BYTE *current = p_data;
    OPJ_UINT32 data_written = 0;

    /* Write SOT marker */
    if (data_written + 6 > p_total_data_size) {
        return OPJ_FALSE;
    }
    current[0] = 0xFF;
    current[1] = 0x90;
    current[2] = (p_j2k->current_tile_number >> 8) & 0xFF;
    current[3] = p_j2k->current_tile_number & 0xFF;
    current[4] = (p_j2k->tile_size_in_bits >> 8) & 0xFF;
    current[5] = p_j2k->tile_size_in_bits & 0xFF;
    current += 6;
    data_written += 6;

    /* Conditionally write tile component information (TUC) if needed */
    if (p_j2k->cinema_mode) {
        if (data_written + 6 > p_total_data_size) {
            return OPJ_FALSE;
        }
        current[0] = 0xFF;
        current[1] = 0x91;
        current[2] = 0x00;
        current[3] = 0x00;
        current[4] = 0x00;
        current[5] = 0x00;
        current += 6;
        data_written += 6;
    }

    /* Write SOD marker */
    if (data_written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    current[0] = 0xFF;
    current[1] = 0x93;
    current += 2;
    data_written += 2;

    *p_data_written = data_written;

    return OPJ_TRUE;
}
